const r = $input.first().json;
const result = r.results?.[0] || r;
const snippet = (result.snippet || '').slice(0, 1500);
const out = {
  ideas: [{
    thesis: snippet || 'Generic strategy from search result',
    market: 'ES',
    timeframe: '15m',
    entry_rules: 'See source for detailed entry conditions',
    exit_rules: 'See source for detailed exit conditions',
    risk_rules: 'See source for detailed risk management',
    source_url: result.url || 'https://unknown',
    regime: 'TRENDING_UP',
    concept_name: (result.title || 'unknown').toLowerCase().replace(/[^a-z0-9]+/g, '_').slice(0, 50),
    source_provider: result.source || 'manual',
    confidence_score: result.fusedScore || 0.5
  }]
};
return [{ json: out }];
